int main(int argc,char**argv){try{if(argc!=4){std::cerr<<"usage: audit_specialization finite_certificate C71_file C72_file\n";return 2;}initfield(nullptr);std::ifstream in(argv[1]);std::string line,name;std::getline(in,line);std::getline(in,line);assert(line=="v_modulus");VF=inup(in);assert(VF.size()==2&&VF[1]==1);U v=kneg(VF[0]);SPoly c71,c72;while(in>>name){if(name=="PASS")break;int n;in>>n;SPoly p(n);for(auto&x:p)x=inup(in);if(name=="allowed_S_modulus")SF=p;if(name=="C71")c71=p;if(name=="C72")c72=p;}for(int k=0;k<2;k++){std::ifstream t(argv[k+2]);QA a=loadq(t);SPoly p(6);for(int i=0;i<6;i++)p[i]=cn(ue(a.n[i],v));U d=ue(a.d,v);if(!d)throw std::runtime_error("audit point has zero denominator");EA got=scale(EA(p),kinv(d));EA expected(k?c72:c71);if(!(got-expected).zero())throw std::runtime_error("generic tail specialization mismatch");}std::cout<<"v="<<v<<" full_S_degree="<<SF.size()-1<<" C71_C72_generic_vs_direct_Ehat_recursion=PASS; bounded implementation audit, not a geometric-locus decision.\n";return 0;}catch(std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
